use super::*;

/// The head helpers a `meta` body imports from `@snapfire/fsr`. Plain
/// functions, so the lowerer inlines each call the way it inlines any
/// module-level helper.
pub(crate) const HEAD_HELPERS: &str = r##"// Generated by fsr build. Do not edit.

/** One element a `meta` body puts in the document head. */
export interface HeadEl {
  tag: string;
  children?: string;
  [attribute: string]: string | undefined;
}

/** One `<meta name>` element. */
export function metaTag(name: string, content: string): HeadEl {
  return { tag: "meta", name, content };
}

/** One `<link>` element. */
export function linkTag(rel: string, href: string): HeadEl {
  return { tag: "link", rel, href };
}

/** A script the page loads once per document, whether it arrives with the first paint or a navigation: now, once the main thread is idle or on the visitor's first interaction. Its origin is added to the policy's `script-src`. */
export function scriptTag(src: string, when?: "load" | "idle" | "interaction"): HeadEl {
  return { tag: "script", src, when };
}

/** An Open Graph property: `og("title", t)` is `<meta property="og:title">`. */
export function og(property: string, content: string): HeadEl {
  return { tag: "meta", property: `og:${property}`, content };
}

/** A Twitter card property: `twitter("card", c)` is `<meta name="twitter:card">`. */
export function twitter(name: string, content: string): HeadEl {
  return { tag: "meta", name: `twitter:${name}`, content };
}

/** A preload of the page's largest image, written into the head so the fetch starts before the stylesheet and the modules parse. `image` is an imported image; `sizes` is what the picture renders at. */
export function preloadImage(image: { src: string; sources?: { type: string; srcset: string }[] }, sizes: string): HeadEl {
  const first = image.sources != null && image.sources.length > 0 ? image.sources[0] : null;
  if (first == null) {
    return { tag: "link", rel: "preload", as: "image", href: image.src, fetchpriority: "high" };
  }
  return { tag: "link", rel: "preload", as: "image", type: first.type, imagesrcset: first.srcset, imagesizes: sizes, fetchpriority: "high" };
}

/** The canonical URL of this page. */
export function canonical(href: string): HeadEl {
  return { tag: "link", rel: "canonical", href };
}

/** When this page last changed, a W3C date such as `2026-06-01` or `2026-06-01T09:30:00Z`: `<meta property="article:modified_time">`, which a sitemap under `[crawl]` writes as the page's `lastmod`. */
export function modified(at: string): HeadEl {
  return { tag: "meta", property: "article:modified_time", content: at };
}

/** What crawlers may do: "noindex, follow" and its kin. */
export function robots(content: string): HeadEl {
  return { tag: "meta", name: "robots", content };
}

/** The browser chrome colour for this page. */
export function themeColor(content: string): HeadEl {
  return { tag: "meta", name: "theme-color", content };
}

/** One icon. Two icons differing only in `sizes` are separate elements, so a page may override one of them. */
export function icon(href: string, sizes: string): HeadEl {
  return { tag: "link", rel: "icon", href, sizes };
}

/** This page in another locale, for search engines. */
export function alternate(href: string, hreflang: string): HeadEl {
  return { tag: "link", rel: "alternate", href, hreflang };
}

/** Structured data, already serialised: `jsonLd(JSON.stringify({ "@type": "TechArticle", headline }))`. A layout's block stays beside its page's. A block they both write is written once. */
export function jsonLd(json: string): HeadEl {
  return { tag: "script", type: "application/ld+json", children: json };
}

/** What a `meta` body returns. */
export interface MetaOf {
  title?: string;
  absolute?: boolean;
  description?: string;
  head: HeadEl[];
}

/** One image of an Open Graph or Twitter card, as Next.js accepts it: a URL or an object naming one. */
type NextImage = string | { url: string; width?: number | string; height?: number | string; alt?: string };

function nextImages(images: NextImage | NextImage[] | null | undefined): { url: string; width?: number | string; height?: number | string; alt?: string }[] {
  if (images == null) {
    return [];
  }
  const list = Array.isArray(images) ? images : [images];
  return list.map((image) => (typeof image === "string" ? { url: image } : image));
}

function cardRows(rows: [string, string | null | undefined][], make: (name: string, content: string) => HeadEl): HeadEl[] {
  return rows.filter(([, content]) => content != null && content !== "").map(([name, content]) => make(name, String(content)));
}

/** A Next.js `Metadata` object, the value `generateMetadata` returns, as `meta` returns it: `title` (a string or `{ absolute }`, `{ default }`), `description`, `alternates` as the canonical and one alternate per language, `openGraph` and `twitter` as their properties and images, `robots` (a string or `{ index, follow }`), `authors`, `facebook` as `fb:app_id` and `fb:admins` and `other` as one `<meta name>` per value. Fields with no head element, `icons`, `manifest` and the title template among them, are left out. */
export function fromNextMetadata(metadata: { [field: string]: any }): MetaOf {
  const title = metadata.title;
  const absolute = title != null && typeof title === "object" && title.absolute != null;
  const titled = title == null ? undefined : typeof title === "string" ? title : absolute ? title.absolute : title.default;
  const alternates = metadata.alternates ?? {};
  const graph = metadata.openGraph ?? {};
  const card = metadata.twitter ?? {};
  const shown = metadata.robots;
  const robotsText = shown == null ? null : typeof shown === "string" ? shown : `${shown.index === false ? "noindex" : "index"}, ${shown.follow === false ? "nofollow" : "follow"}`;
  const authors = metadata.authors == null ? [] : Array.isArray(metadata.authors) ? metadata.authors : [metadata.authors];
  const facebook = metadata.facebook ?? {};
  const admins: unknown[] = facebook.admins == null ? [] : Array.isArray(facebook.admins) ? facebook.admins : [facebook.admins];
  const head: HeadEl[] = [
    ...(alternates.canonical == null ? [] : [canonical(String(alternates.canonical))]),
    ...Object.entries(alternates.languages ?? {}).map(([language, href]) => alternate(String(href), language)),
    ...cardRows([["title", graph.title], ["description", graph.description], ["url", graph.url], ["site_name", graph.siteName], ["type", graph.type]], og),
    ...nextImages(graph.images).flatMap((image) => cardRows([["image", image.url], ["image:width", image.width == null ? null : String(image.width)], ["image:height", image.height == null ? null : String(image.height)], ["image:alt", image.alt]], og)),
    ...cardRows([["card", card.card], ["title", card.title], ["description", card.description], ["site", card.site], ["creator", card.creator]], twitter),
    ...nextImages(card.images).flatMap((image) => cardRows([["image", image.url], ["image:alt", image.alt]], twitter)),
    ...(robotsText == null ? [] : [robots(robotsText)]),
    ...authors.filter((author) => author != null && author.name != null).map((author) => metaTag("author", String(author.name))),
    ...(facebook.appId == null ? [] : [{ tag: "meta", property: "fb:app_id", content: String(facebook.appId) }]),
    ...admins.map((admin) => ({ tag: "meta", property: "fb:admins", content: String(admin) })),
    ...Object.entries(metadata.other ?? {}).flatMap(([name, value]) => (Array.isArray(value) ? value : [value]).filter((each) => each != null).map((each) => metaTag(name, String(each)))),
  ];
  return { ...(titled == null ? {} : { title: titled }), ...(absolute ? { absolute: true } : {}), ...(metadata.description == null ? {} : { description: metadata.description }), head };
}
"##;

/// `[public]` from the configuration beside `app`, each value typed the way
/// a body reads it. A project with no configuration or one the CLI cannot
/// load, declares nothing and `ctx.config` is `{}`.
pub(crate) fn public_of(app: &Path) -> Vec<(String, infer::Ts)> {
  use snapfire_fsr_host::config::PublicValue;
  let root = serve::project_root(app);
  let Ok(config) = snapfire_fsr_host::config::Config::load(&root) else { return Vec::new() };
  config
    .public
    .iter()
    .map(|(key, value)| {
      let ts = match value {
        PublicValue::Str(_) => infer::Ts::Str,
        PublicValue::Int(_) => infer::Ts::Big,
        PublicValue::Float(_) => infer::Ts::Num,
        PublicValue::Bool(_) => infer::Ts::Bool,
      };
      (key.clone(), ts)
    })
    .collect()
}

/// `generated/config.ts`, the module `@snapfire/fsr/config` names: `[public]` as `config` and one export per key, which the server reads as the deployment's values and the browser from the document the host wrote them into.
pub(crate) const CONFIG_MODULE_HEAD: &str = r#"// Generated by fsr build. Do not edit.

import { decodeValue } from "@snapfire/fsr/client";
import type { Config } from "./host";

const written = typeof document === "undefined" ? null : document.getElementById("sf-config");

/** `[public]` from the deployment's configuration, the same on every request. */
export const config = (written?.textContent ? decodeValue(JSON.parse(written.textContent)) : {}) as unknown as Config;
"#;

pub(crate) fn config_module(config: &[(String, infer::Ts)]) -> String {
  let mut out = String::from(CONFIG_MODULE_HEAD);
  for (key, _) in config.iter().filter(|(key, _)| key != "config") {
    let _ = writeln!(out, "export const {key} = config.{key};");
  }
  out
}

/// `generated/host.ts`, the module `@snapfire/fsr/host` names: the per-route params, `Ctx`, `ActionCtx`, the typed `action` and `fail` a body imports and every host standard module.
pub(crate) fn ctx_module(routes: &[Route], session_import: Option<&str>, config: &[(String, infer::Ts)], themes: &[String]) -> String {
  let mut out = String::from("// Generated by fsr build. Do not edit.\n\n");
  out.push_str("export * from \"@snapfire/fsr/host/index\";\nimport { action as declare, after, fail, redirect } from \"@snapfire/fsr/authoring\";\nimport type { Failure, FailureKind, Identity } from \"@snapfire/fsr/authoring\";\nimport type { Services } from \"./services\";\nimport type { Natives } from \"./native\";\nimport type { HeadEl } from \"./head\";\n");
  match session_import {
    Some(path) => {
      let _ = writeln!(out, "import type {{ Session }} from \"{path}\";");
    }
    None => out.push_str("type Session = Record<string, unknown>;\n"),
  }
  out.push_str("\nexport { after, fail, redirect };\nexport type { Failure, FailureKind, Identity, Services, Session };\n\nexport interface Routes {\n");
  for route in routes {
    let params: Vec<String> = route
      .pattern
      .split('/')
      .filter_map(|segment| segment.strip_prefix('{').and_then(|s| s.strip_suffix('}')))
      .map(|name| format!("{}: string", name.trim_start_matches('*')))
      .collect();
    let _ = writeln!(out, "  \"{}\": {{{}}};", route.pattern, if params.is_empty() { String::new() } else { format!(" {} ", params.join("; ")) });
  }
  out.push_str("}\n\n/** `[public]` from the configuration: the deployment's own values, the same on every request. */\nexport interface Config {\n");
  for (key, ts) in config {
    let _ = writeln!(out, "  {key}: {};", ts.print(Flavour::Server));
  }
  out.push_str(
    "}\n\nexport interface Address {\n  path: string;\n  params: Record<string, string>;\n  query: Record<string, string>;\n}\n\nexport interface Ctx<P extends keyof Routes = keyof Routes> {\n  params: Routes[P];\n  query: Record<string, string>;\n  /** The path this request matched, query excluded, locale prefix included. Empty under an action, whose path is the action endpoint rather than the document's. */\n  path: string;\n  session: Session;\n  identity: Identity | null;\n  locale: string;\n  /** The locales the application serves, in the order `[locales]` declares them. The same on every request, so a body reading it still prerenders. */\n  locales: string[];\n  /** The host the request named, when `[server] hosts` lists it; null when it does not, null whenever that key is unset. */\n  host: string | null;\n  /** `document.origin` for this deployment, the scheme and host it is reached over; null when the configuration names none. The same on every request, so a body reading it still prerenders. */\n  origin: string | null;\n  /** The navigation's own request when this render is an intercept, null otherwise. A layout the document keeps loads under the document's request, so `params`, `query` and `path` are the document's there and this is the navigation's. */\n  address: Address | null;\n  /** `[public]` from the configuration, one field per key, typed from the value written there. */\n  config: Config;\n  services: Services;\n  /** The application's own Rust, in this process. A method the build read as `fn` answers a value; an `async fn` answers a promise. */\n  native: Natives;\n  now: bigint;\n}\n\n/** What an action, a route handler or middleware can do to the session beyond reading and writing its keys. */\nexport interface SessionControl {\n  /** Moves the session's end to `seconds` from now once the body commits; the cookie and the store follow. Nothing extends on its own. */\n  extend(seconds: number): void;\n}\n\nexport interface ActionCtx<Input = void, P extends keyof Routes = keyof Routes> extends Ctx<P> {\n  input: Input;\n  session: Session & SessionControl;\n}\n\n/** A `route.ts` handler's context: a loader's plus `session.extend`. */\nexport interface HandlerCtx<P extends keyof Routes = keyof Routes> extends Ctx<P> {\n  session: Session & SessionControl;\n}\n\nexport interface RequestLine {\n  method: string;\n  path: string;\n  /** Whether the request is a navigation's payload rather than a document; absent under a body test. */\n  payload?: boolean;\n  /** The headers `[server] request_headers` lists, by lowercase name. Any other header never reaches a body. */\n  headers: Record<string, string>;\n}\n\nexport interface MiddlewareCtx extends Ctx {\n  request: RequestLine;\n  session: Session & SessionControl;\n  /** Runs the route for `request`, the request as it came when absent. Answers its response, which a middleware returns as it is or changed; it may return a `Response` of its own instead. */\n  next(request?: Request | string): Promise<Response>;\n}\n\nexport interface Meta {\n  title?: string;\n  /** `title` is written as given rather than through `[document] title_template`. */\n  absolute?: boolean;\n  description?: string;\n  head?: HeadEl[];\n}\n\nexport interface MetaCtx<Data, P extends keyof Routes = keyof Routes> {\n  data: Data;\n  params: Routes[P];\n  query: Record<string, string>;\n}\n\nexport type DataOf<Load> = Load extends (...args: never[]) => Promise<infer Data> ? Data : never;\n\nexport function action<Input = void, Out = unknown>(body: (ctx: ActionCtx<Input>) => Promise<Out>): (ctx: ActionCtx<Input>) => Promise<Out> {\n  return declare<Input, Out>(body as never) as never;\n}\n",
  );
  let names: Vec<String> = themes.iter().map(|t| format!("{t:?}")).collect();
  let _ = writeln!(out, "\n/** A named theme: one per file under `styles/themes/` or the root theme as `default`. */\nexport type Theme = {};", if names.is_empty() { "never".to_owned() } else { names.join(" | ") });
  out.push_str("\n/** Light or dark, written as `<html data-sf-scheme>` and independent of the theme. */\nexport type Scheme = \"light\" | \"dark\";\n\n/** The theme the route's layouts and page set: the deepest one, unless a level above it forces its own. */\nexport interface RouteTheme {\n  name: Theme | null;\n  forced: boolean;\n}\n\nexport interface ThemeCtx extends Ctx {\n  theme: RouteTheme;\n}\n\n/** What `theme.ts` decides for the document: no `name` is the root theme, no `scheme` leaves the attribute off. */\nexport interface ThemeChoice {\n  name?: Theme | null;\n  scheme?: Scheme | null;\n}\n");
  out.push_str("\nexport type { HeadEl } from \"./head\";\n");
  out
}

/// `Upload` as TypeScript sees it. A schema names the type without importing
